  game.waveSpawned = 0;
  game.lastDamageAt = 0;
  game.endShown = false;
  game.spawnSerial = 0;
  player.pos.set(0, 0, 12.5);
  player.vel.set(0, 0, 0);
  player.yaw = 0;
  player.pitch = -0.08;
  player.grounded = true;
