+    const halfZ = alongX ? 0.18 : 2.02;
+    return {
+      minX: center.x - halfX,
+      maxX: center.x + halfX,
+      minZ: center.z - halfZ,
+      maxZ: center.z + halfZ,
+      minY: level,
+      maxY: level + 3.2
+    };
+  }
+  if (piece === 'floor') {
+    return {
+      minX: center.x - 2,
+      maxX: center.x + 2,
+      minZ: center.z - 2,
+      maxZ: center.z + 2,
+      minY: level,
+      maxY: level + 0.2
+    };
+  }
+  return {
+    minX: center.x - 2,
+    maxX: center.x + 2,
+    minZ: center.z - 2,
+    maxZ: center.z + 2,
+    minY: level,
+    maxY: level + 3.2
+  };
+}
+
+function placementForCurrentAim() {
+  const level = Math.round(player.pos.y / FLOOR_HEIGHT) * FLOOR_HEIGHT;
+  const yaw = Math.round(player.yaw / (PI / 2)) * (PI / 2);
+  const forward = new THREE.Vector3(-Math.sin(yaw), 0, -Math.cos(yaw));
+  const center = new THREE.Vector3(
+    player.pos.x + forward.x * 4.2,
+    level + (game.piece === 'wall' ? 1.6 : game.piece === 'floor' ? 0.1 : 1.6),
+    player.pos.z + forward.z * 4.2
