+}
+
+function damageBuild(build, amount) {
+  if (!build || build.dead) return;
+  build.hp -= amount;
+  build.flash = 0.12;
+  effects.emit(build.center, build.material === 'wood' ? '#ffc47a' : build.material === 'stone' ? '#d8e4ff' : '#7dfff4', 5, { speed: 2.3, life: 0.3, size: 0.1 });
